// Apply expansion
let totalAdded = 0;
const updatedDecks = defaultDecks.map(deck => {
  const extra = extraCards[deck.id];
  if (!extra) return deck;

  const cardsList = [...deck.cards];
  const existingLength = cardsList.length;
  
  // Format compact cards into full card objects
  extra.forEach((item, index) => {
    const [english, polish, pronunciation, partOfSpeech, exampleEnglish, examplePolish] = item;
    const nextIndex = existingLength + index + 1;
    
    cardsList.push({
      id: `${deck.id}-${nextIndex}`,
      english,
      polish,
      pronunciation,
      partOfSpeech,
      exampleEnglish,
      examplePolish
    });
    totalAdded++;
  });

  return {
    ...deck,
    cards: cardsList
  };
});

// Write defaultDecks.js back
const filePath = './src/data/defaultDecks.js';
const fileContent = `export const defaultDecks = ${JSON.stringify(updatedDecks, null, 2)};\n`;

fs.writeFileSync(filePath, fileContent, 'utf-8');

console.log(`Successfully expanded defaultDecks! Added ${totalAdded} cards. Total cards in database: ${updatedDecks.reduce((sum, d) => sum + d.cards.length, 0)} across ${updatedDecks.length} decks.`);
